        queue = []
        submission = {'user_id': 'child_123', 'status': 'pending', 'submitted_at': datetime.now().isoformat()}

        queue.append(submission)

        assert len(queue) == 1
        assert queue[0]['user_id'] == 'child_123'

    def test_review_queue_ordered_by_submitted_at(self):
        queue = []

        sub1 = {'user_id': 'child_1', 'submitted_at': (datetime.now() - timedelta(hours=2)).isoformat()}
        sub2 = {'user_id': 'child_2', 'submitted_at': (datetime.now() - timedelta(hours=1)).isoformat()}

        queue.append(sub2)
        queue.append(sub1)

        queue.sort(key=lambda x: x['submitted_at'])

        assert queue[0]['user_id'] == 'child_1'
        assert queue[1]['user_id'] == 'child_2'

    def test_operator_review_records_decision(self):
        submission = {'user_id': 'child_123', 'status': 'pending'}

        review = {
            'submission_id': 'child_123',
