class TestIntegrationScenarios:
    def test_complete_referral_flow(self, user_db, pricing_config):
        referrer_id = 'user_123'
        referred_id = 'user_456'
        referral_code = f'REF_{referrer_id}_1234567890'

        # Referrer exists
        user_db[referrer_id] = {'account_balance': 0.0}

        # Referrer creates referral code
        user_db[referrer_id]['referral_code'] = referral_code

        # New user uses referral code
        user_db[referred_id] = {
            'referred_by': referral_code,
            'access_type': 'free',
            'access_via': 'referral',
        }

        # Referrer receives reward
        user_db[referrer_id]['account_balance'] += pricing_config['referral_reward_usd']

        assert user_db[referred_id]['access_type'] == 'free'
        assert user_db[referrer_id]['account_balance'] == 2.50

    def test_complete_event_code_flow(self, user_db, event_code_registry):
        user_id = 'user_789'
        code = 'SSW2026SUMMER'

        # User validates code
        entry = event_code_registry[code]
        is_valid = datetime.fromisoformat(entry['expiry']) > datetime.now() and entry['current_redemptions'] < entry['max_redemptions']

        # User redeems code
        if is_valid:
            user_db[user_id] = {
                'access_type': 'free',
                'access_via': 'event_code',
                'event_code': code,
                'free_months': entry['free_access_months'],
            }
            event_code_registry[code]['current_redemptions'] += 1

        assert user_db[user_id]['access_type'] == 'free'
        assert event_code_registry[code]['current_redemptions'] == 1

    def test_complete_kid_ask_approval_flow(self, user_db, pricing_config):
        child_id = 'child_123'
        operator_id = 'op_456'

        # Child submits request
        submission = {
            'user_id': child_id,
            'video_url': 'https://example.com/video.mp4',
            'text_request': 'I want to make music',
            'status': 'pending',
            'submitted_at': datetime.now().isoformat(),
        }

        # Default approval if enabled
        if pricing_config['kid_ask_default_approval']:
            submission['status'] = 'approved'

        # User gains access
        user_db[child_id] = {
            'access_type': 'free',
            'access_via': 'kid_ask',
            'access_granted_at': datetime.now().isoformat(),
        }

        assert submission['status'] == 'approved'
        assert user_db[child_id]['access_type'] == 'free'

    def test_multiple_access_paths_latest_wins(self, user_db, pricing_config):
        user_id = 'user_111'

        # User gets referral free access
        user_db[user_id] = {'access_type': 'free', 'access_via': 'referral'}

        # User later purchases premium
        user_db[user_id]['access_type'] = 'premium'
        user_db[user_id]['access_via'] = 'paid'
        user_db[user_id]['paid_amount'] = pricing_config['hisanta_premium_usd']

        # Premium should be active access
        assert user_db[user_id]['access_type'] == 'premium'
        assert user_db[user_id]['access_via'] == 'paid'


